class TransferNote {
    final String fromAcct; final String toAcct; final String note;
    TransferNote(String fromAcct, String toAcct, String note) {
            this.fromAcct = fromAcct;
            this.toAcct = toAcct
            this.note = note;
    }
}

// ─── Would be in NoteRenderer.java ───
class NoteRenderer {
    // NEVER DO THIS — writes untrusted input straight into HTML.
    String renderUnsafe(String note) {
        return "<div class='note'>" + note + "</div>";
    }

    // DO THIS — contextual HTML encoding turns code into text.
    String renderSafe(String note) {
        return "<div class='note'>" + escapeHtml(note) + "</div>";
    }

    private String escapeHtml(String s) {
        return s.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#x27;");
    }
}

// ─── Would be in CspPolicy.java ───
class CspPolicy {
    static String header() {
        // Only scripts from our own origin run; inline injected scripts are blocked.
        return "Content-Security-Policy: default-src 'self'; script-src 'self'; object-src 'none'";
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
